CREATE TYPE "SecurityAlertStatus" AS ENUM ('OPEN', 'ACKNOWLEDGED', 'RESOLVED');
CREATE TYPE "PrivacyRequestType" AS ENUM ('EXPORT', 'DELETE', 'ACCESS');
CREATE TYPE "PrivacyRequestStatus" AS ENUM ('REQUESTED', 'UNDER_REVIEW', 'APPROVED', 'PROCESSING', 'COMPLETED', 'REJECTED');
CREATE TYPE "SecurityIncidentStatus" AS ENUM ('OPEN', 'INVESTIGATING', 'CONTAINED', 'RECOVERING', 'RESOLVED', 'CLOSED');

CREATE TABLE "MfaCredential" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "secretCiphertext" TEXT NOT NULL, "encryptionVersion" INTEGER NOT NULL DEFAULT 1, "enabled" BOOLEAN NOT NULL DEFAULT false, "verifiedAt" TIMESTAMP(3), "lastUsedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "MfaCredential_pkey" PRIMARY KEY ("id"));
CREATE TABLE "MfaRecoveryCode" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "credentialId" UUID NOT NULL, "codeHash" TEXT NOT NULL, "usedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MfaRecoveryCode_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SecuritySession" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "sessionId" UUID NOT NULL, "userId" UUID NOT NULL, "workspaceId" UUID, "userAgent" TEXT, "ipAddressHash" TEXT, "lastActivityAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SecuritySession_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SecurityEvent" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID, "organizationId" UUID, "workspaceId" UUID, "action" TEXT NOT NULL, "severity" TEXT NOT NULL, "resource" TEXT, "resourceId" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SecurityEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SecurityAlert" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "eventId" UUID, "workspaceId" UUID, "status" "SecurityAlertStatus" NOT NULL DEFAULT 'OPEN', "severity" TEXT NOT NULL, "kind" TEXT NOT NULL, "summary" TEXT NOT NULL, "actorId" UUID, "acknowledgedAt" TIMESTAMP(3), "resolvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SecurityAlert_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SecurityPolicy" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "organizationId" UUID, "workspaceId" UUID, "requireMfa" BOOLEAN NOT NULL DEFAULT false, "sessionDurationHours" INTEGER NOT NULL DEFAULT 8, "invitationExpiryDays" INTEGER NOT NULL DEFAULT 7, "allowedEmailDomains" TEXT[] NOT NULL, "apiKeysEnabled" BOOLEAN NOT NULL DEFAULT true, "securityNotifications" BOOLEAN NOT NULL DEFAULT true, "updatedById" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SecurityPolicy_pkey" PRIMARY KEY ("id"));
CREATE TABLE "IdentityProviderConfig" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "organizationId" UUID NOT NULL, "providerType" TEXT NOT NULL, "issuer" TEXT NOT NULL, "clientId" TEXT NOT NULL, "encryptedSecret" TEXT NOT NULL, "isEnabled" BOOLEAN NOT NULL DEFAULT false, "enforceSso" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "IdentityProviderConfig_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ApiCredential" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "workspaceId" UUID, "name" TEXT NOT NULL, "keyPrefix" TEXT NOT NULL, "keyHash" TEXT NOT NULL, "scopes" TEXT[] NOT NULL, "expiresAt" TIMESTAMP(3), "lastUsedAt" TIMESTAMP(3), "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ApiCredential_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ServiceAccount" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "workspaceId" UUID NOT NULL, "createdById" UUID NOT NULL, "name" TEXT NOT NULL, "clientId" TEXT NOT NULL, "secretHash" TEXT NOT NULL, "scopes" TEXT[] NOT NULL, "expiresAt" TIMESTAMP(3), "revokedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "ServiceAccount_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SecurityAuditLog" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "organizationId" UUID, "workspaceId" UUID, "actorId" UUID, "action" TEXT NOT NULL, "resource" TEXT NOT NULL, "resourceId" TEXT, "metadata" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SecurityAuditLog_pkey" PRIMARY KEY ("id"));
CREATE TABLE "PrivacyRequest" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "userId" UUID NOT NULL, "workspaceId" UUID, "type" "PrivacyRequestType" NOT NULL, "status" "PrivacyRequestStatus" NOT NULL DEFAULT 'REQUESTED', "reason" TEXT, "exportKey" TEXT, "reviewedById" UUID, "reviewedAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "PrivacyRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DataRetentionPolicy" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "workspaceId" UUID NOT NULL, "dataType" TEXT NOT NULL, "retentionDays" INTEGER NOT NULL, "isEnabled" BOOLEAN NOT NULL DEFAULT true, "updatedById" UUID, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "DataRetentionPolicy_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SecurityIncident" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "workspaceId" UUID, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "severity" TEXT NOT NULL, "status" "SecurityIncidentStatus" NOT NULL DEFAULT 'OPEN', "ownerId" UUID, "resolutionNotes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "SecurityIncident_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SecurityIncidentEvent" ("id" UUID NOT NULL DEFAULT gen_random_uuid(), "incidentId" UUID NOT NULL, "actorId" UUID, "eventType" TEXT NOT NULL, "details" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "SecurityIncidentEvent_pkey" PRIMARY KEY ("id"));

